mapper.select:
select e.`id`, e.`expert_uid`, e.`pro_id`, e.`task_id`, e.`reason`, e.`prev_pro_stat`, e.`created`, e.`deleted`,
    qa.`topic_name` as topicName,
    qa.`group_name` as groupName,
    qa.`apply_id` as proCode,
    (SELECT sd.name FROM sys_dept sd JOIN sys_user su ON sd.dept_id = su.dept_id WHERE su.user_id = qa.opt_uid LIMIT 1) as companyName,
    (SELECT su.name FROM sys_user su WHERE su.user_id = e.expert_uid LIMIT 1) as expertName
from ass_qc_expert_eliminate e
left join ass_qc_group_apply_info qa on e.pro_id = qa.pro_id and e.task_id = qa.task_id

     and e.id = #{id} 
     and e.expert_uid = #{expertUid} 
     and e.pro_id = #{proId} 
     and e.task_id = #{taskId} 
     and e.deleted = #{deleted} 

order by e.id desc


    limit ${offset}, ${limit}

select count(*) from ass_qc_expert_eliminate

     and id = #{id} 
     and expert_uid = #{expertUid} 
     and pro_id = #{proId} 
     and task_id = #{taskId} 
     and deleted = #{deleted}
